-- ============================================
-- LUMA — Thème 14 : MOYEN 1/3 x4 — Une étape imprévue (panne, détour) à gérer
-- ============================================


update scenarios set content = '{"characters": {"operator": "l''opérateur", "mechanic": "le mécanicien"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(Smoke suddenly rises from under the hood. You pull over on an isolated road.)", "text_fr": "(De la fumée s''élève soudainement du capot. Vous vous arrêtez sur une route isolée.)", "choices": [{"text": "(Call roadside assistance immediately.)", "text_fr": "(Appelle l''assistance routière immédiatement.)", "next": "n2"}, {"text": "(Try to check under the hood yourself first.)", "text_fr": "(Essaie de vérifier sous le capot toi-même d''abord.)", "next": "n2b"}]}, "n2": {"speaker": "operator", "text": "Roadside assistance, what''s your situation?", "text_fr": "Assistance routière, quelle est votre situation ?", "choices": [{"text": "My car is smoking, I''m on Route 40, about ten miles from Millbrook.", "text_fr": "Ma voiture fume, je suis sur la Route 40, à environ dix miles de Millbrook.", "next": "n3"}]}, "n2b": {"speaker": "you_thought", "text": "(The smoke intensifies as you approach — clearly not something to fix yourself.)", "text_fr": "(La fumée s''intensifie en vous approchant — clairement pas quelque chose à réparer soi-même.)", "choices": [{"text": "Better call for help instead.", "text_fr": "Mieux vaut appeler à l''aide plutôt.", "next": "n2"}]}, "n3": {"speaker": "operator", "text": "Got it, we''ll dispatch a tow truck. It should arrive within 45 minutes.", "text_fr": "Compris, on envoie une dépanneuse. Elle devrait arriver dans les 45 minutes.", "choices": [{"text": "Thank you, I''ll wait here safely.", "text_fr": "Merci, je vais attendre ici en sécurité.", "next": "n4"}]}, "n4": {"speaker": "you_thought", "text": "(While waiting, you notice a small local garage sign just visible down the road.)", "text_fr": "(En attendant, vous remarquez un petit panneau de garage local juste visible plus loin sur la route.)", "choices": [{"text": "(Walk carefully toward the garage sign to ask about options.)", "text_fr": "(Marche prudemment vers le panneau du garage pour demander des options.)", "next": "n5"}]}, "n5": {"speaker": "mechanic", "text": "Car trouble? I saw the tow truck was called, but I can take a quick look if you want.", "text_fr": "Problème de voiture ? J''ai vu que la dépanneuse a été appelée, mais je peux jeter un œil rapide si vous voulez.", "choices": [{"text": "That would be great, thank you for offering.", "text_fr": "Ce serait super, merci de proposer.", "next": "n6"}]}, "n6": {"speaker": "mechanic", "text": "(Checks under the hood) Looks like a coolant leak — pretty common, fixable today actually.", "text_fr": "(Vérifie sous le capot) On dirait une fuite de liquide de refroidissement — assez courant, réparable aujourd''hui en fait.", "choices": [{"text": "That''s a relief! How much would that repair cost roughly?", "text_fr": "Ça soulage ! Combien coûterait cette réparation environ ?", "next": "n7"}, {"text": "Could you do that repair here at your garage today?", "text_fr": "Vous pourriez faire cette réparation ici à votre garage aujourd''hui ?", "next": "n7"}]}, "n7": {"speaker": "mechanic", "text": "Around $150 for parts and labor, and I could have it ready by this afternoon.", "text_fr": "Environ 150$ pour les pièces et la main-d''œuvre, et je pourrais l''avoir prête cet après-midi.", "choices": [{"text": "That sounds reasonable, let''s do that instead of the tow.", "text_fr": "Ça semble raisonnable, faisons ça plutôt que le remorquage.", "next": "n8"}]}, "n8": {"speaker": "you_thought", "text": "(You cancel the tow truck and follow the mechanic''s truck to his garage nearby.)", "text_fr": "(Vous annulez la dépanneuse et suivez le camion du mécanicien jusqu''à son garage à proximité.)", "choices": [{"text": "(Wait at the garage, relieved to have found a quick solution.)", "text_fr": "(Attends au garage, soulagé d''avoir trouvé une solution rapide.)", "next": "n9"}]}, "n9": {"speaker": "mechanic", "text": "(A few hours later) All fixed! You''re good to hit the road again.", "text_fr": "(Quelques heures plus tard) Tout est réparé ! Vous êtes bon pour reprendre la route.", "choices": [{"text": "Thank you so much, this could have really derailed my whole trip.", "text_fr": "Merci beaucoup, ça aurait vraiment pu faire dérailler tout mon voyage.", "next": "end_fixed"}]}, "end_fixed": {"speaker": "mechanic", "text": "Glad I could help. Drive safe, and enjoy the rest of your road trip!", "text_fr": "Content d''avoir pu aider. Conduisez prudemment, et profitez du reste de votre road trip !", "end": true, "ending_label": "Panne gérée rapidement grâce à un mécano local 🔧🚗"}}}'::jsonb, is_playable = true
where title = 'Une étape imprévue (panne, détour) à gérer'
  and theme_id = (select id from scenario_themes where position = 14 and language_id = (select id from languages where code = 'en'));
